CREATE TABLE app."EmailBlockedDomain" (
  domain text PRIMARY KEY,
  "sourceRevision" text NOT NULL
);
ALTER TABLE app."EmailBlockedDomain" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON app."EmailBlockedDomain" FROM PUBLIC;

-- The Auth hook receives only read access to the public domain blocklist.
-- No SECURITY DEFINER and no browser Data API access is introduced.
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='supabase_auth_admin') THEN
    GRANT USAGE ON SCHEMA app TO supabase_auth_admin;
    GRANT SELECT ON app."EmailBlockedDomain" TO supabase_auth_admin;
    CREATE POLICY auth_hook_domain_read ON app."EmailBlockedDomain" FOR SELECT TO supabase_auth_admin USING (true);
  END IF;
END $$;

CREATE FUNCTION app.before_user_created(event jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
DECLARE email text; domain text; parts text[]; suffix text; i integer;
BEGIN
  email := lower(trim(coalesce(event->'user'->>'email','')));
  IF email = '' OR email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
    RETURN jsonb_build_object('error',jsonb_build_object('http_code',400,'message','A verifiable email address is required.'));
  END IF;
  domain := split_part(email,'@',2);
  IF domain ~ '(^|\.)(invalid|test|localhost|example)$' THEN
    RETURN jsonb_build_object('error',jsonb_build_object('http_code',400,'message','Enter a real email address you can verify.'));
  END IF;
  parts := string_to_array(domain,'.');
  FOR i IN 1..array_length(parts,1) LOOP
    suffix := array_to_string(parts[i:array_length(parts,1)],'.');
    IF suffix IN ('example.com','example.net','example.org') OR EXISTS(SELECT 1 FROM app."EmailBlockedDomain" d WHERE d.domain=suffix) THEN
      RETURN jsonb_build_object('error',jsonb_build_object('http_code',400,'message','Temporary or disposable email addresses are not accepted.'));
    END IF;
  END LOOP;
  RETURN '{}'::jsonb;
END $$;
REVOKE ALL ON FUNCTION app.before_user_created(jsonb) FROM PUBLIC;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='supabase_auth_admin') THEN
    GRANT EXECUTE ON FUNCTION app.before_user_created(jsonb) TO supabase_auth_admin;
  END IF;
END $$;

